\documentclass{article}
\usepackage{amsmath, amsfonts, amssymb}

\begin{document}

\begin{abstract}
We establish functional limit theorems and quantitative rates of convergence for the empirical measures of stationary Feller processes taking values in the Skorokhod path space $\mathbb{D}([0, T], \mathbb{R}^d)$ equipped with the $J_1$ topology. Leveraging the strong Feller property and exponential ergodicity, we derive non-asymptotic error bounds for the pathwise empirical distribution under suitable Wasserstein metrics. We extend these theoretical results to a broad class of stochastic differential equations (SDEs) driven by non-Gaussian Lévy processes with jump discontinuities, establishing explicit convergence rates in terms of the jump-measure characteristics and Lyapunov drift conditions. Finally, we illustrate the practical utility of our functional convergence results in quantitative finance. Specifically, we prove the consistency and error bounds for long-term historical and Monte Carlo estimators used in pricing path-dependent financial derivatives, including Asian, lookback, and barrier options, under general jump-diffusion and heavy-tailed asset price dynamics.

\vspace{0.5em}
\noindent \textbf{Keywords:} Empirical measure, Skorokhod space, Feller process, ergodic theory, Lévy-driven SDEs, option pricing, path-dependent derivatives, Wasserstein distance.
\end{abstract}

\end{document}
